// 具名任职工资沿原组织真实钱包与唯一欠期支付；终态不抹原债。
#include "membership_wages.hpp"
#include "economic_phase_clock.hpp"
#include "local_economy_internal.hpp"
#include "resident/domains/organization/organization_internal.hpp"
#include "resident/domains/organization/named_membership_rules.hpp"
namespace hanmo::resident {
namespace {
using namespace local_economy_detail;
// 工资来源始终指向真实接受事实；普通用户不能构造机构付款授权。
bool binding_source(const CommonStore& c,const OrganizationState& org,const OrganizationCatalog& catalog,const LocalEconomyState& economy,const MembershipWageBinding& b){
    const auto* member=org.members.find(b.member_episode_id);const auto* offer=org.membership_offers.find(b.offer_id);const auto* decision=org.membership_decisions.find(b.decision_id);const auto* terms=catalog.membership_terms.find(b.terms_id);const auto* grant=catalog.grants.find(b.grant_id);const auto* obligation=economy.obligations.find(b.obligation_id);
    if(!catalog.named_membership_enabled||!member||!member->episode_source||!offer||!decision||!terms||!grant||!obligation)return false;
    const auto& source=*member->episode_source;
    return source.wage_binding_id==b.id&&source.offer_id==offer->id&&source.decision_id==decision->id&&source.terms_id==terms->id&&source.joined_tick==b.joined_tick&&source.departed_tick==b.ended_tick
        &&member->actor_id==b.actor_id&&member->organization_id==b.organization_id&&offer->status==MembershipOfferStatus::accepted&&offer->member_episode_id==member->id&&offer->decision_fact_id==decision->id&&offer->terms_id==terms->id&&offer->grant_id==b.grant_id&&offer->office_id==b.office_id&&offer->issuer_actor_id==b.issuer_actor_id&&offer->authority_epoch==b.authority_epoch
        &&decision->kind==MembershipDecisionKind::accept&&decision->offer_id==offer->id&&decision->target_actor_id==b.actor_id&&decision->tick==b.joined_tick
        &&terms->organization_id==b.organization_id&&terms->payer_wallet_id==b.payer_wallet_id&&terms->wage_period_ticks==b.period_ticks&&terms->terminal_fraction_policy_id==b.terminal_fraction_policy_id
        &&grant->amount_limit==b.amount_limit&&grant->office_id==b.office_id&&has(grant->wallet_ids,b.payer_wallet_id)
        &&obligation->principal.kind==SubjectKind::organization&&obligation->principal.id==b.organization_id&&obligation->beneficiary.kind==SubjectKind::actor&&obligation->beneficiary.id==b.actor_id
        &&obligation->kind==ObligationKind::wage&&obligation->source_wallet_or_inventory==b.payer_wallet_id&&obligation->destination==b.payee_wallet_id&&obligation->authority_ref==b.id&&obligation->rate_profile==terms->wage_rate_profile_id&&obligation->period_ticks==b.period_ticks
        &&c.state().facts.find(decision->id)&&c.state().facts.find(source.joined_fact_id);
}
// 新经济事实只用共同ID分配器，失败由外层保存点恢复。
Outcome<StableId> wage_fact(CommonStore& c,const StableId& prefix,const StableId& kind){auto id=c.next_id(prefix);if(!id.ok)return id;auto result=c.append_fact({id.value,kind,"local_economy"});if(!result.ok)return {false,{},result.error};return id;}
}
// 首期按冻结有理工资取当前应付整数；预览不预留未来钱包。
Outcome<Integer> preview_membership_wage(const CommonStore& c,const LocalEconomyCatalog& catalog,const MembershipTerms& terms,const StableId& actor_id,Integer joined_tick){
    const auto* actor=c.actor(actor_id);const auto* source=c.wallet(terms.payer_wallet_id);const auto* rate=catalog.rates.find(terms.wage_rate_profile_id);Integer first_due=0;
    if(!catalog.enabled||!actor||!actor->alive||!source||source->owner.kind!=Owner::Kind::organization||source->owner.id!=terms.organization_id||!rate||rate->per_capita||rate->numerator<0||rate->denominator<=0||terms.wage_period_ticks<=0||terms.continuity_policy_id!="continue_under_organization"||terms.terminal_fraction_policy_id!="terminal_fraction_compensation_v1"||joined_tick<0||!add(joined_tick,terms.wage_period_ticks,first_due))return {false,0,failure("InvalidMembershipWageTerms",terms.id).error};
    const auto* destination=c.wallet(actor->wallet_id);if(!destination||source->id==destination->id||destination->owner.kind!=Owner::Kind::actor||destination->owner.id!=actor_id)return {false,0,failure("InvalidMembershipPayee",actor_id).error};
    auto funds=c.spendable(source->id);if(!funds.ok)return funds;Integer first_amount=rate->numerator/rate->denominator;if(funds.value<first_amount)return {false,0,failure("MembershipFirstWageUnfunded",source->id).error};return {true,first_amount,{}};
}
// 仅真实已加入episode可登记工资，失败不替换经济候选。
Outcome<MembershipWageEffects> register_membership_wage(CommonStore& c,LocalEconomyState& economy,const LocalEconomyCatalog& catalog,const OrganizationState& org,const OrganizationCatalog& org_catalog,const StableId& member_id){
    const auto* member=org.members.find(member_id);if(!org_catalog.named_membership_enabled||!member||!member->episode_source||member->response==MemberResponse::departed)return {false,{},failure("InvalidMembershipWageSource",member_id).error};const auto& source=*member->episode_source;
    const auto* offer=org.membership_offers.find(source.offer_id);const auto* decision=org.membership_decisions.find(source.decision_id);const auto* terms=org_catalog.membership_terms.find(source.terms_id);const auto* grant=offer?org_catalog.grants.find(offer->grant_id):nullptr;
    if(!offer||!decision||!terms||!grant||offer->status!=MembershipOfferStatus::accepted||offer->member_episode_id!=member_id||offer->decision_fact_id!=decision->id||decision->kind!=MembershipDecisionKind::accept||decision->target_actor_id!=member->actor_id||decision->tick!=source.joined_tick||!source.wage_binding_id.empty())return {false,{},failure("InvalidMembershipWageSource",member_id).error};
    for(const auto& row:economy.membership_wage_bindings.rows())if(row.second.member_episode_id==member_id||row.second.decision_id==decision->id)return {false,{},failure("DuplicateMembershipWage",member_id).error};auto preview=preview_membership_wage(c,catalog,*terms,member->actor_id,source.joined_tick);if(!preview.ok)return {false,{},preview.error};
    const auto* rate=catalog.rates.find(terms->wage_rate_profile_id);Integer maximum=rate->numerator/rate->denominator;if(rate->numerator%rate->denominator&&!add(maximum,1,maximum))return {false,{},failure("EconomyQuantityOverflow",terms->id).error};if(grant->amount_limit<maximum||!has(grant->wallet_ids,terms->payer_wallet_id))return {false,{},failure("MembershipWageGrantMismatch",grant->id).error};
    auto next=economy;auto binding_id=c.next_id("membership_wage");if(!binding_id.ok)return {false,{},binding_id.error};auto obligation_id=c.next_id("membership_obligation");if(!obligation_id.ok)return {false,{},obligation_id.error};
    MembershipWageBinding binding;binding.id=binding_id.value;binding.member_episode_id=member_id;binding.obligation_id=obligation_id.value;binding.offer_id=offer->id;binding.decision_id=decision->id;binding.terms_id=terms->id;binding.organization_id=member->organization_id;binding.actor_id=member->actor_id;binding.payer_wallet_id=terms->payer_wallet_id;binding.payee_wallet_id=c.actor(member->actor_id)->wallet_id;binding.grant_id=grant->id;binding.office_id=offer->office_id;binding.issuer_actor_id=offer->issuer_actor_id;binding.authority_epoch=offer->authority_epoch;binding.joined_tick=source.joined_tick;binding.first_due_tick=source.joined_tick+terms->wage_period_ticks;binding.frozen_numerator=rate->numerator;binding.frozen_denominator=rate->denominator;binding.period_ticks=terms->wage_period_ticks;binding.amount_limit=grant->amount_limit;binding.terminal_fraction_policy_id=terms->terminal_fraction_policy_id;
    RecurringObligation obligation;obligation.id=obligation_id.value;obligation.principal={SubjectKind::organization,member->organization_id};obligation.beneficiary={SubjectKind::actor,member->actor_id};obligation.kind=ObligationKind::wage;obligation.source_wallet_or_inventory=binding.payer_wallet_id;obligation.destination=binding.payee_wallet_id;obligation.rate_profile=terms->wage_rate_profile_id;obligation.authority_ref=binding.id;obligation.period_ticks=binding.period_ticks;obligation.next_due_tick=binding.first_due_tick;
    next.obligations.insert(obligation.id,obligation);next.obligation_remainders.insert(obligation.id,0);next.membership_wage_bindings.insert(binding.id,binding);economy=std::move(next);MembershipWageEffects effects;effects.binding_id=binding.id;effects.obligation_id=obligation.id;return {true,std::move(effects),{}};
}
// 历史工资授权只沿原接受绑定与原雇主钱包，撤职后仍保留旧债。
bool membership_wage_authorized(const CommonStore& c,const OrganizationState& org,const OrganizationCatalog& catalog,const LocalEconomyState& economy,const StableId& authority_ref,const StableId& obligation_id,const StableId& principal,const StableId& source,Integer amount,Integer tick){
    const auto* wallet=c.wallet(source);return wallet&&wallet->owner.kind==Owner::Kind::organization&&wallet->owner.id==principal&&membership_wage_source_authorized(c,org,catalog,economy,authority_ref,obligation_id,principal,source,amount,tick);
}
bool membership_wage_source_authorized(const CommonStore& c,const OrganizationState& org,const OrganizationCatalog& catalog,const LocalEconomyState& economy,const StableId& authority_ref,const StableId& obligation_id,const StableId& principal,const StableId& source,Integer amount,Integer tick){
    const auto* binding=economy.membership_wage_bindings.find(authority_ref);const auto* wallet=c.wallet(source);if(!binding||!wallet||binding->obligation_id!=obligation_id||binding->organization_id!=principal||binding->payer_wallet_id!=source||tick<binding->joined_tick||amount<0||amount>binding->amount_limit)return false;return binding_source(c,org,catalog,economy,*binding);
}
// 合法离职与一次余数结算原子成立；清零余数同时必须建立对应整数应付。
Outcome<MembershipWageEffects> finish_membership_wage(CommonStore& c,LocalEconomyState& economy,const LocalEconomyCatalog&,const OrganizationState& org,const OrganizationCatalog& catalog,const StableId& member_id,Integer tick,const StableId& departure_fact,const CurrentMomentRead* actual_clock){
    auto actual=read_economic_calendar_tick(c,actual_clock);if(!actual.ok)return {false,{},actual.error};
    const auto* member=org.members.find(member_id);const auto* fact=org.facts.find(departure_fact);if(!member||!member->episode_source||member->response!=MemberResponse::departed||member->episode_source->departed_tick!=std::optional<Integer>(tick)||member->episode_source->departure_fact_id!=departure_fact||!fact||fact->kind!="organization_member_response"||fact->response!=MemberResponse::departed||fact->actor_id!=member->actor_id||fact->organization_id!=member->organization_id||fact->tick!=tick)return {false,{},failure("InvalidMembershipTerminalSource",member_id).error};
    const auto* old_binding=economy.membership_wage_bindings.find(member->episode_source->wage_binding_id);if(!old_binding||old_binding->ended_tick||!old_binding->terminal_fact_id.empty()||tick<old_binding->joined_tick||tick!=actual.value)return {false,{},failure("MembershipWageAlreadyEnded",member_id).error};
    auto next=economy;auto& binding=*next.membership_wage_bindings.find(old_binding->id);auto* obligation=next.obligations.find(binding.obligation_id);auto* remainder=next.obligation_remainders.find(binding.obligation_id);if(!obligation||!remainder||*remainder<0||*remainder>=binding.frozen_denominator||(*remainder>0&&(binding.credited_periods<=0||binding.last_credited_due_tick<=binding.joined_tick||binding.last_credited_due_tick>tick)))return {false,{},failure("InvalidMembershipTerminalFraction",member_id).error};
    binding.ended_tick=tick;obligation->active=false;OrganizationAccess access(c,org,catalog,next);LocalEconomyEffects paid;auto settled=local_economy_detail::settle_obligation_arrears(c,next,access,*obligation,tick,paid);if(!settled.ok)return {false,{},settled.error};
    auto id=wage_fact(c,"membership_terminal","membership_wage_ended");if(!id.ok)return {false,{},id.error};MembershipTerminalFractionReceipt receipt;receipt.id=id.value;receipt.wage_binding_id=binding.id;receipt.member_episode_id=member_id;receipt.obligation_id=binding.obligation_id;receipt.departure_fact_id=departure_fact;receipt.tick=tick;receipt.original_numerator=*remainder;receipt.denominator=binding.frozen_denominator;
    if(*remainder>0){receipt.compensation_numerator=binding.frozen_denominator-*remainder;receipt.integer_due=1;auto arrear=wage_fact(c,"local_due","wage_due");if(!arrear.ok)return {false,{},arrear.error};receipt.arrear_id=arrear.value;next.arrears.insert(arrear.value,{arrear.value,binding.obligation_id,tick,1,0});obligation->last_receipt_id=arrear.value;paid.fact_ids.push_back(arrear.value);paid.receipt_ids.push_back(arrear.value);}
    *remainder=0;binding.terminal_fact_id=id.value;next.membership_terminal_fractions.insert(id.value,receipt);settled=local_economy_detail::settle_obligation_arrears(c,next,access,*obligation,tick,paid);if(!settled.ok)return {false,{},settled.error};MembershipWageEffects effects;effects.binding_id=binding.id;effects.obligation_id=binding.obligation_id;effects.fact_ids=std::move(paid.fact_ids);effects.receipt_ids=std::move(paid.receipt_ids);effects.fact_ids.push_back(id.value);effects.receipt_ids.push_back(id.value);economy=std::move(next);return {true,std::move(effects),{}};
}
// 每个实际服务期重演纯整数商余数，工资回执数量和账期必须与冻结日历相同。
Status validate_membership_wages(const CommonStore& c,const LocalEconomyState& economy,const LocalEconomyCatalog& economy_catalog,const OrganizationState& org,const OrganizationCatalog& catalog,const CurrentMomentRead* actual_clock){
    auto actual=read_economic_calendar_tick(c,actual_clock);if(!actual.ok)return {false,{},actual.error};
    std::set<StableId> episodes,obligations,terminals,terminal_arrears;
    for(const auto& row:economy.membership_wage_bindings.rows()){const auto& b=row.second;const auto* obligation=economy.obligations.find(b.obligation_id);const auto* rate=obligation?economy_catalog.rates.find(obligation->rate_profile):nullptr;const auto* saved=economy.obligation_remainders.find(b.obligation_id);Integer first=0,next=0,elapsed=0;const auto* actor=c.actor(b.actor_id);
        if(row.first!=b.id||b.id.empty()||!binding_source(c,org,catalog,economy,b)||!episodes.insert(b.member_episode_id).second||!obligations.insert(b.obligation_id).second||economy_catalog.obligations.find(b.obligation_id)||!actor||actor->wallet_id!=b.payee_wallet_id||!rate||rate->per_capita||b.frozen_numerator<0||b.frozen_denominator<=0||b.frozen_numerator!=rate->numerator||b.frozen_denominator!=rate->denominator||b.period_ticks<=0||b.joined_tick<0||b.joined_tick>actual.value||b.credited_periods<0||b.amount_limit<0||b.terminal_fraction_policy_id!="terminal_fraction_compensation_v1"||!saved||!add(b.joined_tick,b.period_ticks,first)||first!=b.first_due_tick||!multiply(b.credited_periods,b.period_ticks,elapsed)||!add(first,elapsed,next)||obligation->next_due_tick!=next||obligation->active==bool(b.ended_tick)||!obligation->item_id.empty())return failure("InvalidMembershipWageBinding",row.first);
        Integer maximum=b.frozen_numerator/b.frozen_denominator;if(b.frozen_numerator%b.frozen_denominator&&!add(maximum,1,maximum))return failure("EconomyQuantityOverflow",row.first);if(maximum>b.amount_limit)return failure("MembershipWageGrantMismatch",row.first);
        const Integer end=b.ended_tick?*b.ended_tick:economy.last_step_tick;if(end<b.joined_tick||end>actual.value||b.credited_periods!=(end-b.joined_tick)/b.period_ticks||b.last_credited_due_tick!=(b.credited_periods?next-b.period_ticks:0))return failure("InvalidMembershipCreditedPeriods",row.first);
        const MembershipTerminalFractionReceipt* terminal=nullptr;if(b.ended_tick){terminal=economy.membership_terminal_fractions.find(b.terminal_fact_id);if(!terminal||!terminals.insert(terminal->id).second)return failure("MissingMembershipTerminalFraction",row.first);}else if(!b.terminal_fact_id.empty())return failure("PrematureMembershipTerminalFraction",row.first);
        std::vector<const ArrearRecord*> dues;for(const auto& item:economy.arrears.rows())if(item.second.obligation_id==b.obligation_id&&(!terminal||item.first!=terminal->arrear_id))dues.push_back(&item.second);std::sort(dues.begin(),dues.end(),[](const auto* a,const auto* other){return a->due_tick<other->due_tick;});if(Integer(dues.size())!=b.credited_periods)return failure("MembershipWagePeriodCountMismatch",row.first);
        Integer remainder=0,due_tick=first;for(const auto* due:dues){Integer amount=0,fraction=0;if(!ratio(1,b.frozen_numerator,b.frozen_denominator,remainder,amount,fraction)||due->due_tick!=due_tick||due->original_due!=amount||!add(due_tick,b.period_ticks,due_tick))return failure("MembershipWagePeriodMismatch",due->id);remainder=fraction;}
        if(!terminal){if(*saved!=remainder)return failure("MembershipWageRemainderMismatch",row.first);continue;}
        const auto* member=org.members.find(b.member_episode_id);const auto* header=c.state().facts.find(terminal->id);if(terminal->wage_binding_id!=b.id||terminal->member_episode_id!=b.member_episode_id||terminal->obligation_id!=b.obligation_id||terminal->departure_fact_id!=member->episode_source->departure_fact_id||terminal->tick!=*b.ended_tick||terminal->original_numerator!=remainder||terminal->denominator!=b.frozen_denominator||terminal->compensation_numerator!=(remainder?b.frozen_denominator-remainder:0)||terminal->integer_due!=(remainder?1:0)||*saved!=0||!header||header->domain!="local_economy"||header->kind!="membership_wage_ended")return failure("InvalidMembershipTerminalFraction",terminal->id);
        if(remainder){const auto* arrear=economy.arrears.find(terminal->arrear_id);if(b.credited_periods==0||b.last_credited_due_tick<=b.joined_tick||!arrear||arrear->obligation_id!=b.obligation_id||arrear->due_tick!=terminal->tick||arrear->original_due!=1||!terminal_arrears.insert(arrear->id).second)return failure("InvalidMembershipTerminalArrear",terminal->id);}else if(!terminal->arrear_id.empty())return failure("ZeroMembershipTerminalArrear",terminal->id);
    }
    if(terminals.size()!=economy.membership_terminal_fractions.size())return failure("OrphanMembershipTerminalFraction");for(const auto& row:economy.membership_terminal_fractions.rows())if(row.first!=row.second.id)return failure("InvalidMembershipTerminalFraction",row.first);for(const auto& row:org.members.rows())if(row.second.episode_source&&!episodes.count(row.first))return failure("MissingMembershipWageBinding",row.first);return common_success();
}
} // 恢复只验证来源，绝不重放终态补偿。
